public class PagedResponse<T>
{
    public List<T> Items { get; set; } = new();
    public string? NextCursor { get; set; }
    public bool HasMore { get; set; }
    public int PageSize { get; set; }
}

public async Task<PagedResponse<OrderDto>> GetOrdersAsync(
    string? cursor, int pageSize, CancellationToken ct)
{
    var lastId = DecodeCursor(cursor);
    var query = _db.Orders.AsQueryable();

    if (lastId.HasValue)
        query = query.Where(o => o.Id > lastId.Value);

    var items = await query
        .OrderBy(o => o.Id)
        .Take(pageSize + 1)
        .ToListAsync(ct);

    var hasMore = items.Count > pageSize;
    if (hasMore) items = items.Take(pageSize).ToList();

    return new PagedResponse<OrderDto>
    {
        Items = items.Adapt<List<OrderDto>>(),
        NextCursor = hasMore ? EncodeCursor(items.Last().Id) : null,
        HasMore = hasMore,
        PageSize = pageSize
    };
}

public IQueryable<Order> ApplySorting(
    IQueryable<Order> query,
    string? sortBy,
    string? sortOrder)
{
    var allowed = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        nameof(Order.CreatedUtc), nameof(Order.Total), nameof(Order.Id)
    };

    var descending = sortOrder?.ToLower() == "desc";
    var column = allowed.Contains(sortBy ?? string.Empty)
        ? sortBy!
        : nameof(Order.CreatedUtc);

    query = descending
        ? query.OrderByDescending(e => EF.Property<object>(e, column))
        : query.OrderBy(e => EF.Property<object>(e, column));

    return query.ThenBy(e => e.Id);
}
